package com.tal.pocketflow;
import android.app.*;import android.content.*;import android.os.Looper;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import java.time.*;import java.util.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,qualifiers="he-rIL-w411dp-h891dp-xxhdpi")
public class PlanningTest{
 Context c;Store db;long account;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();c.deleteDatabase("pocketflow.db");c.getSharedPreferences("prefs",0).edit().clear().commit();c.getSharedPreferences("security",0).edit().clear().commit();c.getSharedPreferences("browser-sync",0).edit().clear().commit();c.getSharedPreferences("reminder-local",0).edit().clear().commit();db=new Store(c);Store.Account a=new Store.Account();a.name="בנק";a.type="bank";a.start="2025-01-01";a.closing=31;a.charge=10;db.save(a);account=a.id;}
 @After public void close(){db.close();}
 Store.Tx tx(String date,long amount,String category,int status){Store.Tx t=new Store.Tx();t.date=date;t.amount=amount;t.originalAmount=amount;t.category=category;t.merchant="חנות";t.tag="";t.note="";t.account=account;t.kind="expense";t.count=1;t.status=status;db.save(t);return t;}
 Store.Rule rule(String date,int interval){Store.Rule r=new Store.Rule();r.name="מנוי";r.amount=12000;r.category="חשבונות";r.account=account;r.start=date;r.end="";r.active=1;r.interval=interval;db.save(r);return r;}
 @Test public void partialMonthComparisonExcludesLaterDaysAndPending(){tx("2026-10-01",10000,"אוכל",1);tx("2026-10-20",90000,"אוכל",1);tx("2026-11-01",15000,"אוכל",1);tx("2026-11-02",50000,"אוכל",0);List<Analytics.Insight> list=new Analytics(db,c).insights(YearMonth.of(2026,11),LocalDate.parse("2026-11-05"));assertTrue(list.stream().anyMatch(i->i.title.contains("50%")));assertTrue(new Analytics(db,c).insights(YearMonth.of(2026,12),LocalDate.parse("2026-11-05")).isEmpty());}
 @Test public void yearlyAndQuarterlyGenerateOnlyTheirOwnMonthsAndSurviveBackup()throws Exception{Store.Rule annual=rule("2025-01-31",12),quarter=rule("2026-01-31",3);db.ensureMonth(YearMonth.of(2026,6));assertEquals(2,db.transactions().stream().filter(t->t.rule==annual.id).count());assertEquals(2,db.transactions().stream().filter(t->t.rule==quarter.id).count());JSONObject backup=db.backup();db.restore(backup);assertEquals(12,db.rules().stream().filter(r->r.id==annual.id).findFirst().get().interval);assertEquals(LocalDate.parse("2026-04-30"),Analytics.next(quarter,LocalDate.parse("2026-02-01")));}
 @Test public void renewalsRespectEndDatePauseAndManualDeadline(){Store.Rule r=rule("2026-01-31",12);r.reminderDays=10;db.save(r);assertEquals(1,new Analytics(db,c).renewals(LocalDate.parse("2027-01-25")).size());r.active=0;db.save(r);assertTrue(new Analytics(db,c).renewals(LocalDate.parse("2027-01-25")).isEmpty());r.active=1;r.renewal="2026-11-03";db.save(r);assertEquals(1,new Analytics(db,c).renewals(LocalDate.parse("2026-11-01")).size());}
 @Test public void budgetMatchesOverviewAndDismissalDoesNotDeleteTransactions()throws Exception{Store.Tx t=tx("2026-11-01",10000,"בית",1);tx("2026-11-01",10000,"בית",1);tx("2026-11-02",5000,"בית",0);Analytics a=new Analytics(db,c);assertEquals(db.overview(YearMonth.of(2026,11)).total(),a.spend(YearMonth.of(2026,11),""));List<Analytics.Issue> issues=a.quality(LocalDate.parse("2026-11-05"));assertEquals(2,issues.size());Tools.dismiss(c,issues.get(0).key);assertEquals(1,a.quality(LocalDate.parse("2026-11-05")).size());assertEquals(3,db.transactions().size());JSONObject backup=db.backup();db.restore(backup);assertTrue(Tools.dismissed(c,issues.get(0).key));}
 @Test public void toolsRejectInvalidBudgetAndRoundTripPortablePreferences()throws Exception{JSONObject data=new JSONObject().put("budgets",new JSONObject().put("",50000)).put("homeCards",new JSONArray(Arrays.asList("summary","recent")));Tools.write(c,data,true);JSONObject backup=db.backup();db.restore(backup);assertEquals(50000,Tools.budgets(c).getLong(""));assertEquals(Arrays.asList("summary","recent"),Tools.cards(c));JSONObject invalid=new JSONObject(backup.toString());invalid.getJSONObject("settings").getJSONObject("tools").getJSONObject("budgets").put("",-1);try{db.restore(invalid);fail();}catch(IllegalArgumentException expected){}assertEquals(50000,Tools.budgets(c).getLong(""));}
 @Test public void legacyVersionFiveRestoresNewRuleDefaults()throws Exception{rule("2026-01-31",1);JSONObject backup=db.backup();backup.put("version",5);for(int i=0;i<backup.getJSONArray("rules").length();i++){JSONObject r=backup.getJSONArray("rules").getJSONObject(i);r.remove("interval_months");r.remove("reminder_days");r.remove("renewal");}backup.getJSONObject("settings").remove("tools");db.restore(backup);assertEquals(1,db.rules().get(0).interval);assertEquals(7,db.rules().get(0).reminderDays);assertTrue(Tools.templates(c).length()==0);}
 @Test public void variableEstimateExcludesRecurringPendingAndInstallments(){tx("2026-08-01",30000,"בית",1);tx("2026-09-01",60000,"בית",1);Store.Tx installment=tx("2026-10-01",90000,"בית",1);Store.Account credit=new Store.Account();credit.name="אשראי";credit.type="credit";credit.start="2025-01-01";credit.closing=31;credit.charge=10;db.save(credit);installment.account=credit.id;installment.count=3;db.save(installment);tx("2026-10-02",5000,"בית",0);assertEquals(30000,new Analytics(db,c).variableAverage(YearMonth.of(2026,11)));}
 @Test public void allNewPagesNavigateAndHomeSectionsAreCustomizable()throws Exception{Tools.write(c,new JSONObject().put("homeCards",new JSONArray(Arrays.asList("summary","recent"))),false);try(ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=controller.get();assertNotNull(a.getWindow().getDecorView().findViewWithTag("home-total"));StoreTest.navigate(a,11);assertNull(a.getWindow().getDecorView().findViewWithTag("chart-selector"));assertNotNull(a.getWindow().getDecorView().findViewWithTag("home-section-recent"));for(int tab:new int[]{7,8,9,10}){StoreTest.navigate(a,tab);assertNotNull(a.getWindow().getDecorView().findViewWithTag("menu-toggle"));}a.onBackPressed();assertFalse(a.isFinishing());}}
 @Test public void reusingTransactionRequiresExplicitSaveAndUsesToday()throws Exception{Store.Tx original=tx("2026-01-01",12500,"בית",1);try(ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=controller.get();java.lang.reflect.Method copy=MainActivity.class.getDeclaredMethod("reusable",Store.Tx.class);copy.setAccessible(true);Store.Tx seed=(Store.Tx)copy.invoke(a,original);assertEquals(0,seed.id);assertEquals(0,seed.rule);assertEquals(LocalDate.now().toString(),seed.date);java.lang.reflect.Method form=MainActivity.class.getDeclaredMethod("transactionDialog",Store.Tx.class);form.setAccessible(true);form.invoke(a,seed);Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals(1,db.transactions().size());AlertDialog dialog=ShadowAlertDialog.getLatestAlertDialog();dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertFalse(ShadowToast.getTextOfLatestToast(),dialog.isShowing());assertEquals(2,db.transactions().size());}}
}
